escenas.Mundo:
// Mundo compartido: «Qué significa de verdad el 60% de lluvia».
// Una maqueta de paisaje en corte (mar, playa, ciudad, calle) bajo un cielo gris, con un celular rojo grande a la derecha.
// paso 0: maqueta, cielo gris, celular con 60%. La persona sostiene la canasta de picnic.
// paso 1: la canasta está en el suelo y un sol asoma detrás de la nube.
// paso 2: aparece la línea del camino del dato, con todos los tramos apagados.
// paso 3: el globo sonda sube y se enciende el tramo 1.
// paso 4: el satélite escanea las nubes y el mar ya se ve iluminado. Se enciende el tramo 2.
// paso 5: aparece la estación meteorológica en la calle. Se enciende el tramo 3.
// paso 6: aparece la supercomputadora al final de la línea, el cielo se divide en cubos y se enciende el tramo 4.
// paso 7: además de lo anterior, hay una pila de números sueltos y la supercomputadora vuelve a estar encendida.
// paso 8: el cielo queda libre (la escena dibuja las dos simulaciones).
// paso 9: los mini cielos del ensamble aparecen en fila, mezclados.
// paso 10: casi todos los mini cielos llueven y se ven verdes. El medidor de confianza está alto.
// paso 11: no hay mini cielos. El camino está entero encendido y el 60% está partido en dos.
// paso 12: el 60% vuelve a estar entero, con la zona sombreada del mapa y el medidor en 80.
// paso 13: el reloj tachado y las dos nubes con lluvias de distinta duración. (El paraguas lo agrega la escena 13.)
import React from 'react';
import * as THREE from 'three';
import {Pieza, Linea, Cartel, Flecha, Brillo, ConoDeLuz, Muneco, Paleta} from '../lib3d';

export const PARTES = [
  'camino', 'celular', 'persona', 'canasta', 'sol', 'globo', 'satelite', 'haz', 'mar', 'estacion',
  'supercomputadora', 'cubos', 'numeros', 'minicielos', 'medidor', 'zona', 'reloj', 'nubeslluvia', 'paraguas',
] as const;

export type ParteProps = {paleta: Paleta; resaltado?: boolean; frame?: number};
export type MundoProps = {paso: number; frame: number; fps: number; paleta: Paleta; ocultar?: string[]; resaltar?: string[]};

const TINTA = '#1B1B1F';
const SUELO_Y = 0.16;
const col = (p: Paleta, r: boolean | undefined, c: string) => (r ? p.acentos[2] : c);

// ---------- Ayudas de estado por paso ----------
export const tramosEncendidos = (paso: number) =>
  paso >= 11 ? 5 : paso >= 6 ? 4 : paso >= 5 ? 3 : paso >= 4 ? 2 : paso >= 3 ? 1 : 0;
export const marVisible = (paso: number) => paso >= 4;
export const confianza = (paso: number) => (paso >= 12 ? 0.8 : paso >= 10 ? 0.9 : 0.2);
export const minicieloLluvioso = (i: number, paso: number) => (paso >= 10 ? i !== 5 : [0, 2, 3, 6].includes(i));

// Puntos del camino del dato (suelo → globo → satélite → estación → supercomputadora → celular)
export const PUNTOS_CAMINO: [number, number, number][] = [
  [-1.02, 0.19, 0.4], [-0.62, 0.19, 0.4], [-0.18, 0.19, 0.4], [0.25, 0.19, 0.4], [0.38, 0.19, 0.0], [0.7, 0.19, 0.12],
];
export const POS_CELULAR: [number, number, number] = [0.85, SUELO_Y, 0.08];
export const POS_SUPER: [number, number, number] = [0.38, SUELO_Y, -0.18];

// Geometrías de aristas para piezas transparentes (sin contorno opaco)
const aristasCubo = new THREE.EdgesGeometry(new THREE.BoxGeometry(0.18, 0.18, 0.18));
const aristasCielo = new THREE.EdgesGeometry(new THREE.BoxGeometry(0.13, 0.17, 0.13));
const Aristas: React.FC<{g: THREE.BufferGeometry; color?: string}> = ({g, color = TINTA}) => (
  <lineSegments geometry={g}>
    <lineBasicMaterial color={color} />
  </lineSegments>
);

const Nube: React.FC<{posicion: [number, number, number]; escala?: number; color?: string}> = ({posicion, escala = 1, color = '#9EA3A8'}) => (
  <group position={posicion} scale={escala}>
    <Pieza forma="esfera" medidas={[0.13]} color={color} posicion={[0, 0, 0]} escala={[1, 0.8, 0.9]} />
    <Pieza forma="esfera" medidas={[0.1]} color={color} posicion={[-0.14, -0.03, 0.02]} escala={[1, 0.8, 0.9]} />
    <Pieza forma="esfera" medidas={[0.1]} color={color} posicion={[0.15, -0.03, 0]} escala={[1, 0.8, 0.9]} />
    <Pieza forma="esfera" medidas={[0.08]} color={color} posicion={[0.05, 0.08, -0.03]} />
  </group>
);

// ---------- Partes ----------
export const Mar: React.FC<ParteProps & {visible?: boolean}> = ({paleta, resaltado, frame = 0, visible = true}) => {
  const agua = col(paleta, resaltado, visible ? '#3A8FD0' : '#2B3445');
  const ola = Math.sin(frame / 18) * 0.004;
  return (
    <group position={[-0.85, 0, -0.25]}>
      <Pieza forma="caja" medidas={[0.6, 0.12, 0.5]} color={agua} posicion={[0, 0.07 + ola, 0]} />
      {visible ? (
        <group position={[0.05, 0.14 + ola, 0.02]} rotation={[0, Math.sin(frame / 40) * 0.1, Math.sin(frame / 15) * 0.05]}>
          <Pieza forma="caja" medidas={[0.14, 0.03, 0.05]} color="#F2EFE8" />
          <Pieza forma="caja" medidas={[0.04, 0.04, 0.035]} color="#D2452F" posicion={[-0.02, 0.035, 0]} />
        </group>
      ) : (
        <Cartel texto="?" posicion={[0, 0.3, 0]} alto={0.2} fondo="transparent" colorTexto="#FFFFFF" borde={TINTA} />
      )}
    </group>
  );
};

export const Celular: React.FC<ParteProps & {dividido?: boolean}> = ({paleta, resaltado, frame = 0, dividido = false}) => {
  const cuerpo = col(paleta, resaltado, paleta.acentos[0]);
  const pulso = 1 + Math.sin(frame / 20) * 0.015;
  return (
    <group position={POS_CELULAR} rotation={[0, -0.4, 0]}>
      <group position={[0, 0.46, 0]} rotation={[-0.08, 0, 0]}>
        <Pieza forma="caja" medidas={[0.44, 0.86, 0.06]} color={cuerpo} />
        <Pieza forma="caja" medidas={[0.38, 0.74, 0.01]} color="#9ED8F5" posicion={[0, 0.01, 0.032]} contorno={false} />
        <Pieza forma="capsula" medidas={[0.012, 0.06]} color={TINTA} posicion={[0, 0.405, 0.034]} rotacion={[0, 0, Math.PI / 2]} contorno={false} />
        <group position={[0, 0.18, 0.045]} scale={pulso}>
          <Pieza forma="esfera" medidas={[0.07]} color="#FFFFFF" escala={[1, 0.8, 0.3]} />
          <Pieza forma="esfera" medidas={[0.05]} color="#FFFFFF" posicion={[-0.08, -0.02, 0]} escala={[1, 0.8, 0.3]} />
          <Pieza forma="esfera" medidas={[0.05]} color="#FFFFFF" posicion={[0.08, -0.02, 0]} escala={[1, 0.8, 0.3]} />
        </group>
        {dividido ? (
          <>
            <Cartel texto="6" posicion={[-0.09, -0.08, 0.05]} alto={0.2} fondo="transparent" colorTexto="#FFFFFF" borde={paleta.acentos[2]} rotacion={[0.0001, 0, 0]} />
            <Cartel texto="0%" posicion={[0.09, -0.11, 0.05]} alto={0.2} fondo="transparent" colorTexto="#FFFFFF" borde={paleta.acentos[2]} rotacion={[0.0001, 0, 0]} />
            <Cartel texto="?" posicion={[-0.1, -0.27, 0.05]} alto={0.1} fondo="transparent" colorTexto="#FFFFFF" borde={TINTA} rotacion={[0.0001, 0, 0]} />
            <Cartel texto="?" posicion={[0.1, -0.27, 0.05]} alto={0.1} fondo="transparent" colorTexto="#FFFFFF" borde={TINTA} rotacion={[0.0001, 0, 0]} />
          </>
        ) : (
          <Cartel texto="60%" posicion={[0, -0.1, 0.05]} alto={0.22} fondo="transparent" colorTexto="#FFFFFF" borde="#2E6FA8" rotacion={[0.0001, 0, 0]} />
        )}
        <Cartel texto="SÚPER NIÑO" posicion={[0, -0.395, 0.035]} alto={0.035} fondo="transparent" colorTexto="#FFFFFF" rotacion={[0.0001, 0, 0]} />
      </group>
      {/* soporte trasero */}
      <Pieza forma="caja" medidas={[0.16, 0.4, 0.03]} color="#3A3A40" posicion={[0, 0.2, -0.12]} rotacion={[0.45, 0, 0]} />
      <Pieza forma="caja" medidas={[0.3, 0.03, 0.2]} color="#3A3A40" posicion={[0, 0.015, -0.04]} />
    </group>
  );
};

export const Camino: React.FC<ParteProps & {encendidos?: number}> = ({paleta, resaltado, frame = 0, encendidos = 0}) => {
  const luz = paleta.acentos[2];
  return (
    <group>
      {PUNTOS_CAMINO.slice(0, -1).map((p, i) => {
        const on = i < encendidos || resaltado;
        return <Linea key={i} desde={p} hasta={PUNTOS_CAMINO[i + 1]} grosor={on ? 0.014 : 0.01} color={on ? luz : '#5E5B57'} brillo={on} />;
      })}
      {PUNTOS_CAMINO.map((p, i) => (
        <Pieza key={`n${i}`} forma="esfera" medidas={[0.022]} color={i <= encendidos ? luz : '#5E5B57'} posicion={p}
          brillo={i <= encendidos && encendidos > 0 ? luz : undefined} intensidad-brillo={0} escala={1 + (i <= encendidos && encendidos > 0 ? Math.sin(frame / 8 + i) * 0.15 : 0)} />
      ))}
    </group>
  );
};

export const Persona: React.FC<ParteProps> = ({paleta, resaltado, frame}) => (
  <Muneco color={col(paleta, resaltado, '#3C6FB4')} posicion={[0.5, SUELO_Y, 0.34]} rotacion={1.0} altura={0.3} conCara={false} brazoDer={0.5} frame={frame} />
);

export const Canasta: React.FC<ParteProps & {caida?: boolean}> = ({paleta, resaltado, caida = false}) => {
  const mimbre = col(paleta, resaltado, '#C98B4F');
  return (
    <group position={caida ? [0.44, SUELO_Y + 0.025, 0.46] : [0.47, SUELO_Y + 0.11, 0.42]} rotation={caida ? [0.2, 0.6, 1.4] : [0, 0.6, 0]}>
      <Pieza forma="caja" medidas={[0.08, 0.05, 0.055]} color={mimbre} />
      <Pieza forma="toro" medidas={[0.032, 0.005, Math.PI]} color="#9C6535" posicion={[0, 0.025, 0]} />
      <Pieza forma="caja" medidas={[0.082, 0.012, 0.057]} color="#D2452F" posicion={[0, 0.02, 0]} contorno={false} />
    </group>
  );
};

export const Sol: React.FC<ParteProps> = ({paleta, resaltado, frame = 0}) => (
  <group position={[0.45, 1.62, -0.45]} rotation={[0, 0, frame * 0.01]}>
    <Pieza forma="esfera" medidas={[0.14]} color={col(paleta, resaltado, '#F6C744')} brillo="#F6B42C" />
    {[0, 1, 2, 3, 4, 5, 6, 7].map((i) => (
      <Pieza key={i} forma="cono" medidas={[0.025, 0.07]} color="#F6C744" contorno={false}
        posicion={[Math.cos((i * Math.PI) / 4) * 0.19, Math.sin((i * Math.PI) / 4) * 0.19, 0]} rotacion={[0, 0, (i * Math.PI) / 4 - Math.PI / 2]} />
    ))}
  </group>
);

export const Globo: React.FC<ParteProps> = ({paleta, resaltado, frame = 0}) => {
  const y = 1.12 + Math.sin(frame / 25) * 0.03;
  return (
    <group position={[-0.78, y, 0.22]} rotation={[0, 0, Math.sin(frame / 30) * 0.05]}>
      <Pieza forma="esfera" medidas={[0.11]} color={col(paleta, resaltado, '#F7F4EE')} escala={[1, 1.12, 1]} />
      <Pieza forma="cono" medidas={[0.03, 0.04]} color="#E9E4DB" posicion={[0, -0.13, 0]} rotacion={[Math.PI, 0, 0]} />
      <Linea desde={[0, -0.15, 0]} hasta={[0, -0.3, 0]} grosor={0.003} color={TINTA} />
      <Pieza forma="caja" medidas={[0.06, 0.05, 0.05]} color="#E0A526" posicion={[0, -0.33, 0]} />
      <Pieza forma="cilindro" medidas={[0.004, 0.004, 0.05]} color="#5E5B57" posicion={[0.02, -0.38, 0]} contorno={false} />
    </group>
  );
};

export const Satelite: React.FC<ParteProps> = ({paleta, resaltado, frame = 0}) => (
  <group position={[-0.82, 1.8, -0.25]} rotation={[0.3, frame * 0.004, 0.15]}>
    <Pieza forma="caja" medidas={[0.12, 0.1, 0.1]} color={col(paleta, resaltado, '#C8CCD2')} metal={0.6} />
    {[-1, 1].map((l) => (
      <group key={l}>
        <Linea desde={[0.06 * l, 0, 0]} hasta={[0.1 * l, 0, 0]} grosor={0.006} color="#8A8F96" />
        <Pieza forma="caja" medidas={[0.2, 0.005, 0.09]} color="#2F5FB8" posicion={[0.2 * l, 0, 0]} />
      </group>
    ))}
    <Pieza forma="cilindro" medidas={[0.04, 0.015, 0.03]} color="#E9E4DB" posicion={[0, -0.065, 0]} />
  </group>
);

export const Haz: React.FC<ParteProps> = ({paleta, resaltado, frame = 0}) => (
  <group>
    <ConoDeLuz posicion={[-0.85, 0.14, -0.25]} altura={1.6} radio={0.32} color={col(paleta, resaltado, '#A3D9FF')} opacidad={0.12} />
    <group position={[-0.85, 1.05, -0.25]} rotation={[-Math.PI / 2, 0, frame * 0.02]}>
      <Pieza forma="toro" medidas={[0.16, 0.035, Math.PI * 1.6]} color="#F2F2F2" />
      <Pieza forma="toro" medidas={[0.08, 0.03, Math.PI * 1.5]} color="#F2F2F2" rotacion={[0, 0, 2]} />
    </group>
  </group>
);

export const Estacion: React.FC<ParteProps> = ({paleta, resaltado, frame = 0}) => {
  const blanco = col(paleta, resaltado, '#F2EFE8');
  return (
    <group position={[-0.2, SUELO_Y, 0.27]}>
      <Pieza forma="cilindro" medidas={[0.008, 0.01, 0.42]} color="#8A8F96" posicion={[0, 0.21, 0]} />
      <Pieza forma="caja" medidas={[0.07, 0.07, 0.05]} color={blanco} posicion={[0, 0.2, 0.02]} />
      <group position={[0, 0.43, 0]} rotation={[0, frame * 0.3, 0]}>
        {[0, 1, 2].map((i) => {
          const a = (i * Math.PI * 2) / 3;
          return (
            <group key={i}>
              <Linea desde={[0, 0, 0]} hasta={[Math.cos(a) * 0.06, 0, Math.sin(a) * 0.06]} grosor={0.003} color={TINTA} />
              <Pieza forma="media_esfera" medidas={[0.018]} color={blanco} posicion={[Math.cos(a) * 0.06, 0, Math.sin(a) * 0.06]} rotacion={[0, -a, Math.PI / 2]} />
            </group>
          );
        })}
      </group>
      {/* pluviómetro transparente con agua */}
      <group position={[0.1, 0, 0.02]}>
        <Pieza forma="cilindro" medidas={[0.025, 0.025, 0.04]} color="#3A8FD0" posicion={[0, 0.03, 0]} contorno={false} />
        <Pieza forma="cilindro" medidas={[0.03, 0.03, 0.14]} color="#DDF1FF" opacidad={0.35} posicion={[0, 0.07, 0]} contorno={false} />
        <Pieza forma="toro" medidas={[0.03, 0.004]} color={TINTA} posicion={[0, 0.14, 0]} rotacion={[Math.PI / 2, 0, 0]} contorno={false} />
      </group>
    </group>
  );
};

export const Supercomputadora: React.FC<ParteProps & {encendida?: boolean}> = ({paleta, resaltado, frame = 0, encendida = true}) => (
  <group position={POS_SUPER} rotation={[0, -0.2, 0]}>
    <Pieza forma="caja" medidas={[0.3, 0.56, 0.24]} color={col(paleta, resaltado, '#202127')} posicion={[0, 0.28, 0]} />
    <Pieza forma="caja" medidas={[0.32, 0.03, 0.26]} color="#3A3A40" posicion={[0, 0.575, 0]} />
    {[0, 1, 2, 3, 4, 5].map((r) =>
      [0, 1, 2].map((c) => {
        const on = encendida && (Math.floor(frame / 6) + r + c) % 3 !== 0;
        return (
          <Pieza key={`${r}-${c}`} forma="caja" medidas={[0.06, 0.015, 0.01]} color={on ? '#5CC8FF' : '#2C3440'} contorno={false}
            brillo={on ? '#3FB4FF' : undefined} posicion={[-0.08 + c * 0.08, 0.1 + r * 0.075, 0.122]} />
        );
      }),
    )}
    {encendida ? <Brillo posicion={[0, 0.3, 0.2]} color="#5CC8FF" radio={0.001} luz={0.6} /> : null}
  </group>
);

export const Cubos: React.FC<ParteProps & {gris?: boolean}> = ({paleta, resaltado, frame = 0, gris = false}) => {
  const items: React.ReactNode[] = [];
  for (let i = 0; i < 5; i++)
    for (let j = 0; j < 2; j++)
      for (let k = 0; k < 2; k++) {
        const p: [number, number, number] = [-0.75 + i * 0.2, 0.85 + j * 0.2, -0.15 + k * 0.2];
        const a = Math.sin(frame / 30 + i * 1.3 + j * 2.1 + k) * 1.2;
        items.push(
          <group key={`${i}${j}${k}`} position={p}>
            <mesh>
              <boxGeometry args={[0.18, 0.18, 0.18]} />
              <meshBasicMaterial color={gris ? '#9A9A9A' : col(paleta, resaltado, '#BFE6FF')} transparent opacity={0.12} depthWrite={false} />
            </mesh>
            <Aristas g={aristasCubo} color={gris ? '#6E6E6E' : '#3E7FB8'} />
            {gris ? null : <Flecha desde={[-Math.cos(a) * 0.05, 0, -Math.sin(a) * 0.05]} hasta={[Math.cos(a) * 0.05, 0, Math.sin(a) * 0.05]} color={paleta.acentos[3]} grosor={0.007} />}
          </group>,
        );
      }
  return <group>{items}</group>;
};

export const Numeros: React.FC<ParteProps> = ({paleta, resaltado}) => {
  const n = ['7', '23', '0.4', '98', '5', '12', '61', '3'];
  return (
    <group position={[0.05, SUELO_Y, 0.15]}>
      {n.map((t, i) => (
        <Cartel key={i} texto={t} posicion={[((i * 37) % 7) * 0.035 - 0.1, 0.04 + Math.floor(i / 3) * 0.05, ((i * 13) % 5) * 0.02]} alto={0.07}
          fondo="transparent" colorTexto={col(paleta, resaltado, '#F7F4EE')} borde={TINTA} />
      ))}
    </group>
  );
};

export const MiniCielos: React.FC<ParteProps & {paso?: number}> = ({paleta, resaltado, frame = 0, paso = 9}) => (
  <group>
    {[0, 1, 2, 3, 4, 5, 6, 7].map((i) => {
      const lluvia = minicieloLluvioso(i, paso);
      const verde = paso >= 10 && lluvia;
      const x = -0.75 + i * 0.16;
      return (
        <group key={i} position={[x, 1.25 + Math.sin(frame / 20 + i) * 0.01, 0.2]}>
          <mesh>
            <boxGeometry args={[0.13, 0.17, 0.13]} />
            <meshBasicMaterial color={verde ? paleta.acentos[2] : col(paleta, resaltado, lluvia ? '#AFC6D8' : '#CFEAFF')} transparent opacity={verde ? 0.3 : 0.2} depthWrite={false} />
          </mesh>
          <Aristas g={aristasCielo} color={verde ? '#5E8A12' : '#4A6C88'} />
          {lluvia ? (
            <>
              <Pieza forma="esfera" medidas={[0.04]} color="#8E959C" posicion={[0, 0.04, 0]} escala={[1.4, 0.8, 1]} />
              {[-0.025, 0, 0.025].map((dx, d) => (
                <Pieza key={d} forma="capsula" medidas={[0.005, 0.015]} color="#3A8FD0" contorno={false} posicion={[dx, -0.02 - ((frame + d * 7) % 15) * 0.003, 0]} />
              ))}
            </>
          ) : (
            <Pieza forma="esfera" medidas={[0.03]} color="#F6C744" brillo="#F6B42C" posicion={[0, 0.02, 0]} />
          )}
        </group>
      );
    })}
  </group>
);

export const Medidor: React.FC<ParteProps & {valor?: number}> = ({paleta, resaltado, valor = 0.8}) => {
  const ang = Math.PI * (1 - valor);
  return (
    <group position={[0.4, 1.12, 0.3]} rotation={[0, -0.3, 0]}>
      <Pieza forma="cilindro" medidas={[0.17, 0.17, 0.02]} color="#F7F4EE" rotacion={[Math.PI / 2, 0, 0]} />
      <Pieza forma="toro" medidas={[0.13, 0.018, Math.PI * 0.5]} color="#D2452F" posicion={[0, 0, 0.012]} rotacion={[0, 0, Math.PI / 2]} contorno={false} />
      <Pieza forma="toro" medidas={[0.13, 0.018, Math.PI * 0.5]} color={col(paleta, resaltado, paleta.acentos[2])} posicion={[0, 0, 0.012]} contorno={false} />
      <Linea desde={[0, 0, 0.025]} hasta={[Math.cos(ang) * 0.12, Math.sin(ang) * 0.12, 0.025]} grosor={0.007} color={TINTA} />
      <Pieza forma="esfera" medidas={[0.015]} color={TINTA} posicion={[0, 0, 0.025]} contorno={false} />
      <Cartel texto={`${Math.round(valor * 100)}%`} posicion={[0, -0.07, 0.03]} alto={0.07} fondo="transparent" colorTexto={TINTA} rotacion={[0.0001, 0, 0]} />
    </group>
  );
};

export const Zona: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <group position={[-0.3, 1.25, 0.1]} rotation={[1.1, 0, 0]}>
    <Pieza forma="caja" medidas={[0.6, 0.02, 0.44]} color="#E9E4DB" />
    {[-0.2, -0.05, 0.1, 0.22].map((x, i) => (
      <Pieza key={i} forma="caja" medidas={[0.08, 0.03, 0.08]} color="#C2BBAF" posicion={[x, 0.02, (i % 2) * 0.15 - 0.08]} contorno={false} />
    ))}
    <mesh position={[-0.075, 0.04, 0]}>
      <boxGeometry args={[0.45, 0.005, 0.44]} />
      <meshBasicMaterial color={col(paleta, resaltado, '#3A8FD0')} transparent opacity={0.45} depthWrite={false} />
    </mesh>
