// ---------- Mundo ----------
export const Mundo: React.FC<MundoProps> = ({paso, frame, paleta, ocultar = [], resaltar = []}) => {
  const ver = (n: string) => !ocultar.includes(n);
  const r = (n: string) => resaltar.includes(n);
  const hay = (desde: number) => paso >= desde;
  const entre = (a: number, b: number) => paso >= a && paso <= b;
  const comun = {paleta, frame};
  return (
    <group>
      <Maqueta frame={frame} />
      {ver('mar') ? <Mar {...comun} resaltado={r('mar')} visible={marVisible(paso)} /> : null}
      {ver('celular') ? <Celular {...comun} resaltado={r('celular')} dividido={paso === 11} /> : null}
      {ver('persona') ? <Persona {...comun} resaltado={r('persona')} /> : null}
      {ver('canasta') ? <Canasta {...comun} resaltado={r('canasta')} caida={hay(1)} /> : null}
      {hay(1) && ver('sol') ? <Sol {...comun} resaltado={r('sol')} /> : null}
      {hay(2) && ver('camino') ? <Camino {...comun} resaltado={r('camino')} encendidos={tramosEncendidos(paso)} /> : null}
      {hay(3) && ver('globo') ? <Globo {...comun} resaltado={r('globo')} /> : null}
      {hay(4) && ver('satelite') ? <Satelite {...comun} resaltado={r('satelite')} /> : null}
      {hay(4) && ver('haz') ? <Haz {...comun} resaltado={r('haz')} /> : null}
      {hay(5) && ver('estacion') ? <Estacion {...comun} resaltado={r('estacion')} /> : null}
      {hay(6) && ver('supercomputadora') ? <Supercomputadora {...comun} resaltado={r('supercomputadora')} encendida /> : null}
      {entre(6, 7) && ver('cubos') ? <Cubos {...comun} resaltado={r('cubos')} /> : null}
      {paso === 7 && ver('numeros') ? <Numeros {...comun} resaltado={r('numeros')} /> : null}
      {entre(9, 10) && ver('minicielos') ? <MiniCielos {...comun} resaltado={r('minicielos')} paso={paso} /> : null}
      {entre(10, 12) && ver('medidor') ? <Medidor {...comun} resaltado={r('medidor')} valor={confianza(paso)} /> : null}
      {paso === 12 && ver('zona') ? <Zona {...comun} resaltado={r('zona')} /> : null}
      {hay(13) && ver('reloj') ? <Reloj {...comun} resaltado={r('reloj')} /> : null}
      {hay(13) && ver('nubeslluvia') ? <NubesLluvia {...comun} resaltado={r('nubeslluvia')} /> : null}
      {hay(14) && ver('paraguas') ? <Paraguas {...comun} resaltado={r('paraguas')} /> : null}
    </group>
  );
};
